import{_ as n,C as a,o as l,c as h,j as t,a as e,E as o,a5 as c}from"./chunks/framework.Dep_XxFZ.js";const P=JSON.parse('{"title":"抽屉","description":"","frontmatter":{},"headers":[],"relativePath":"components/drawer.md","filePath":"components/drawer.md","lastUpdated":1787365442000}'),s={name:"components/drawer.md"},p={id:"抽屉",tabindex:"-1"};function b(g,d,u,x,w,f){const i=a("Badge"),r=a("XhDemo");return l(),h("div",null,[t("h1",p,[d[0]||(d[0]=e("抽屉 ",-1)),o(i,{type:"info",text:"drawer"}),d[1]||(d[1]=e()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#抽屉","aria-label":'Permalink to "抽屉 <Badge type="info" text="drawer" />"'},"​",-1))]),d[3]||(d[3]=c('<p>从屏幕某一边滑出的面板。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>内容比对话框长（一整张表单、一份详情），但仍属于当前上下文。</li><li>窄屏上的导航或筛选面板。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只是确认一件事：用<a href="./dialog">对话框</a>或<a href="./popconfirm">弹出确认</a>。</li><li>内容需要与页面主体对照着看：并排展开，别遮住。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>side</code> 决定从哪一边出来；<code>contained</code> 让它只占据某个容器而不是整个视口。</li><li>可以拖边缘改厚度。</li><li>关闭前可以拦截（有未保存改动时先问一句）。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>不传 open 即为非受控；Escape 关闭、Tab 在面板里循环，展开期间页面滚不动</p>',10)),o(r,{src:"drawer/01-basic"}),d[4]||(d[4]=t("h3",{id:"贴边方向",tabindex:"-1"},[e("贴边方向 "),t("a",{class:"header-anchor",href:"#贴边方向","aria-label":'Permalink to "贴边方向"'},"​")],-1)),d[5]||(d[5]=t("p",null,"side 只落成 data-side，面板压在哪条边由皮肤按这个值决定；root 与 content 报的是同一条边",-1)),o(r,{src:"drawer/02-side"}),d[6]||(d[6]=t("h3",{id:"受控",tabindex:"-1"},[e("受控 "),t("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),d[7]||(d[7]=t("p",null,"传了 open 就由宿主说了算；Escape、点面板外、按叉都只回写 open，不自己改状态",-1)),o(r,{src:"drawer/03-controlled"}),d[8]||(d[8]=t("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),t("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[9]||(d[9]=t("p",null,"size 落成 content 的 data-size，只改面板贴边方向上的厚度；三档各自一个抽屉，点开才看得出厚薄",-1)),o(r,{src:"drawer/04-size"}),d[10]||(d[10]=t("h3",{id:"内容滚动",tabindex:"-1"},[e("内容滚动 "),t("a",{class:"header-anchor",href:"#内容滚动","aria-label":'Permalink to "内容滚动"'},"​")],-1)),d[11]||(d[11]=t("p",null,"面板本身定高，把中间那段设成可伸缩并开滚动，标题与底部操作就钉在两头",-1)),o(r,{src:"drawer/05-scroll"}),d[12]||(d[12]=t("h3",{id:"关闭前拦截",tabindex:"-1"},[e("关闭前拦截 "),t("a",{class:"header-anchor",href:"#关闭前拦截","aria-label":'Permalink to "关闭前拦截"'},"​")],-1)),d[13]||(d[13]=t("p",null,"受控时组件不自改状态：Escape、点面板外、按叉都只发一次收起意图，写不写由宿主定",-1)),o(r,{src:"drawer/06-guard"}),d[14]||(d[14]=t("h3",{id:"拖边缘改厚度",tabindex:"-1"},[e("拖边缘改厚度 "),t("a",{class:"header-anchor",href:"#拖边缘改厚度","aria-label":'Permalink to "拖边缘改厚度"'},"​")],-1)),d[15]||(d[15]=t("p",null,"面板里放一根把手，拖动时把新厚度写进 content 的 --xh-drawer-size；这个槽压过 size 三档，滑入滑出仍按面板自身宽度算",-1)),o(r,{src:"drawer/07-resize"}),d[16]||(d[16]=t("h3",{id:"局部抽屉",tabindex:"-1"},[e("局部抽屉 "),t("a",{class:"header-anchor",href:"#局部抽屉","aria-label":'Permalink to "局部抽屉"'},"​")],-1)),d[17]||(d[17]=t("p",null,"把抽屉收进某块区域：遮罩与定位层从 fixed 换成 absolute，只罩住那块区域而不是盖满整屏",-1)),o(r,{src:"drawer/08-contained"}),d[18]||(d[18]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-drawer&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhDrawerCloseTrigger</code> <code>XhDrawerContent</code> <code>XhDrawerDescription</code> <code>XhDrawerRoot</code> <code>XhDrawerTitle</code> <code>XhDrawerTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useDrawer</code></td></tr><tr><td>状态机</td><td><code>drawerMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/drawer.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;drawer&quot;</code>：<strong><code>root</code></strong> · <code>trigger</code> · <code>backdrop</code> · <code>positioner</code> · <strong><code>content</code></strong> · <code>title</code> · <code>description</code> · <code>close-trigger</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>modal</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>contained</code></td><td><code>boolean</code></td><td></td><td>浮层挂在某个局部容器里而不是视口：遮罩与定位层从 fixed 换成 absolute， 于是只罩住那个容器、不再盖满整屏。 挂到哪个容器是适配器的事（Vue 由 root 的 container 决定，WC 本就是 Light DOM、 作者写在哪就在哪），这里只表达「按局部容器画」这一件事。</td></tr><tr><td><code>side</code></td><td><code>DrawerSide</code></td><td></td><td>从哪条边滑出，默认 &#39;right&#39;。只影响输出的 data-side，不参与状态转移。</td></tr><tr><td><code>role</code></td><td><code>&#39;dialog&#39; | &#39;alertdialog&#39;</code></td><td></td><td></td></tr><tr><td><code>closeOnEscape</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>closeOnInteractOutside</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>restoreFocus</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。横放时换面板宽度、竖放时换面板高度，随 side 而定。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;DrawerTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: DrawerOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图回调；受控时是唯一出口，非受控时随内部转移一并通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>DrawerOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhDrawerRoot</code></td><td><code>default</code></td><td><code>DrawerRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>backdrop</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>open</code> · <code>closed</code></p><p><strong>事件</strong>：<code>OPEN</code> · <code>TOGGLE</code> · <code>CLOSE</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code></p><p><strong>判据</strong>：<code>isOpenControlled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useDrawer</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>side</code></td><td><code>DrawerSide</code></td><td>已解析的滑出边（prop 缺省时是默认值），作者据此配动画。</td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getBackdropProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPositionerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDescriptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCloseTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in trigger</td><td>打开抽屉并把焦点移入 content</td></tr><tr><td><code>Escape</code></td><td>open</td><td>关闭并把焦点还给 trigger</td></tr><tr><td><code>Tab</code></td><td>open 且 modal</td><td>在 content 内向后循环焦点</td></tr><tr><td><code>Shift+Tab</code></td><td>open 且 modal</td><td>在 content 内向前循环焦点</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-haspopup</code></td><td>&#39;dialog&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-describedby</code></td><td><code>description</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>aria-labelledby</code></td><td><code>title</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>aria-modal</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>props.role</td></tr><tr><td><code>close-trigger</code></td><td><code>aria-label</code></td><td>props.translations.close</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/drawer.css</code> 按部件选择：<code>[data-scope=&quot;drawer&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-contained</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-side</code></td><td>props.side</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>backdrop</code></td><td><code>data-contained</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>backdrop</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-contained</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-positioned</code></td><td>&#39;&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-contained</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>content</code></td><td><code>data-side</code></td><td>props.side</td></tr><tr><td><code>content</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-drawer-backdrop-bg</code> · <code>--xh-drawer-backdrop-layer</code> · <code>--xh-drawer-bg</code> · <code>--xh-drawer-close-bg-active</code> · <code>--xh-drawer-close-bg-hover</code> · <code>--xh-drawer-close-radius</code> · <code>--xh-drawer-close-size</code> · <code>--xh-drawer-description-fg</code> · <code>--xh-drawer-fg</code> · <code>--xh-drawer-gap</code> · <code>--xh-drawer-icon-size</code> · <code>--xh-drawer-layer</code> · <code>--xh-drawer-px</code> · <code>--xh-drawer-py</code> · <code>--xh-drawer-radius</code> · <code>--xh-drawer-shadow</code> · <code>--xh-drawer-size</code> · <code>--xh-drawer-title-fg</code> · <code>--xh-drawer-title-font-size</code> · <code>--xh-drawer-title-font-weight</code> · <code>--xh-drawer-trigger-bg</code> · <code>--xh-drawer-trigger-bg-hover</code> · <code>--xh-drawer-trigger-bg-open</code> · <code>--xh-drawer-trigger-border</code> · <code>--xh-drawer-trigger-border-hover</code> · <code>--xh-drawer-trigger-border-open</code> · <code>--xh-drawer-trigger-fg</code> · <code>--xh-drawer-trigger-font-size</code> · <code>--xh-drawer-trigger-font-weight</code> · <code>--xh-drawer-trigger-gap</code> · <code>--xh-drawer-trigger-h</code> · <code>--xh-drawer-trigger-px</code> · <code>--xh-drawer-trigger-radius</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-drawer-in-bottom</code> · <code>xh-drawer-in-left</code> · <code>xh-drawer-in-right</code> · <code>xh-drawer-in-top</code> · <code>xh-drawer-out-bottom</code> · <code>xh-drawer-out-left</code> · <code>xh-drawer-out-right</code> · <code>xh-drawer-out-top</code> · <code>xh-fade-in</code> · <code>xh-fade-out</code> 随皮肤自带，不引用别处文件里的名字；状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>里面放<a href="./form">表单</a>、<a href="./side-nav">侧栏导航</a>；内容区套<a href="./scroll-area">滚动区域</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>提交与取消固定在底部，别让用户滚到最下面才找得到。</li><li>有未保存改动时拦下关闭。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>抽屉里再开抽屉。</li><li>在宽屏上用抽屉装本可以直接展开的内容。</li></ul>',48))])}const q=n(s,[["render",b]]);export{P as __pageData,q as default};
